22	type ServiceSignal<TState> = ReturnType<typeof signal<TState>>;
23	type RuntimeQueryDefinition<TState> = QueryDefinition<TState, AnySchema, AnySchema>;
24	type RegisteredService = ServiceInstance<unknown, Queries<unknown>, Commands<unknown>>;
25	type StaticStateLoader = (input: unknown) => Promise<void>;
26	
27	/**
28	 * Internal runtime object returned while a service instance is being assembled.
29	 *
30	 * It keeps the raw signal and `self` reference available for static building and store-backed
31	 * preloading, while callers typically consume the simpler `ServiceInstance` shape.
32	 */
33	export type ServiceRuntime<
34	  TState,
35	  TQueries extends Queries<TState>,
36	  TCommands extends Commands<TState>,
37	> = {
38	  stateSignal: ServiceSignal<TState>;
39	  selfRef: WritableSelf<TState>;
40	  queryCtx: QueryCtx<TState>;
41	  commands: ServiceInstance<TState, TQueries, TCommands>['commands'];
42	  queries: ServiceInstance<TState, TQueries, TCommands>['queries'];
43	};
44	
45	/**
46	 * Resolves which serialized static-state file should back a query input.
47	 *
48	 * Queries without a custom `static.path()` share one default file per service.
49	 */
50	export function resolveStaticPath<TState>(
51	  serviceId: string,
52	  queryDef: RuntimeQueryDefinition<TState>,
53	  input: unknown,
54	  ctx: QueryCtx<TState>
55	): string {
56	  return queryDef.static?.path ? queryDef.static.path(input, ctx) : `${serviceId}.json`;
57	}
58	
59	/**
60	 * Creates the mutable `self` object shared by runtime contexts.
61	 *
62	 * State writes are wrapped in an alien-signals batch so one command can update multiple fields
63	 * without causing unnecessary intermediate reactive notifications.
64	 */
65	function createSelfRef<TState>(stateSignal: ServiceSignal<TState>): WritableSelf<TState> {
66	  return {
67	    get state() {
68	      return stateSignal();
69	    },
70	    setState(mutate) {
71	      // Batch signal writes so one command only triggers subscribers after the full draft update.
72	      startBatch();
73	      try {
74	        stateSignal(produce(stateSignal(), mutate));
75	      } finally {
76	        endBatch();
77	      }
78	    },
79	    queries: {},
80	    commands: {},
81	  };
82	}
