3	import { createServiceRuntime, resolveStaticPath } from './service-runtime.ts';
4	import { validateSchema } from './service-validation.ts';
5	import type {
6	  AnySchema,
7	  BuildTaskResult,
8	  Commands,
9	  Queries,
10	  QueryDefinition,
11	  ServiceDefinition,
12	  StaticStore,
13	} from './types.ts';
14	
15	type RuntimeServiceDefinition = ServiceDefinition<unknown, Queries<unknown>, Commands<unknown>>;
16	type RuntimeQueryDefinition = QueryDefinition<unknown, AnySchema, AnySchema>;
17	
18	/**
19	 * Builds the serialized static-state snapshots for a set of services.
20	 *
21	 * For every query that declares both `preload` and `static.inputs`, this function:
22	 * - creates a fresh runtime from the service's initial state
23	 * - resolves all static inputs
24	 * - validates each input exactly like a runtime call would
25	 * - runs preload for that input
26	 * - stores the resulting state under the resolved static path
27	 *
28	 * Snapshots that land on the same path are deep-merged so multiple queries can contribute to one
29	 * serialized state file.
30	 */
31	export async function buildStaticFiles(services: RuntimeServiceDefinition[]): Promise<StaticStore> {
32	  const store: StaticStore = {};
33	  const buildTasks: Promise<BuildTaskResult>[] = [];
34	
35	  for (const service of services) {
36	    for (const [queryName, query] of Object.entries(service.queries) as [
37	      string,
38	      RuntimeQueryDefinition,
39	    ][]) {
40	      if (!query.preload || !query.static?.inputs) {
41	        continue;
42	      }
43	
44	      // Resolve the static input list from a clean runtime so discovery cannot leak state.
45	      const inputsRuntime = createServiceRuntime(
46	        service,
47	        undefined,
48	        structuredClone(service.initialState)
49	      );
50	      const inputs = await query.static.inputs(inputsRuntime.queryCtx);
51	
52	      buildTasks.push(
53	        ...inputs.map(async (input) => {
54	          // Each input gets its own fresh runtime so the snapshot only reflects that preload path.
55	          const buildRuntime = createServiceRuntime(
56	            service,
57	            undefined,
58	            structuredClone(service.initialState)
59	          );
60	          const validatedInput = await validateSchema(query.input, input, {
61	            kind: 'query',
62	            serviceId: service.id,
63	            name: queryName,
64	            phase: 'input',
65	          });
66	          const path = resolveStaticPath(service.id, query, validatedInput, buildRuntime.queryCtx);
67	
68	          // Run the same preload logic used at runtime, but capture the resulting state to disk.
69	          await query.preload!(validatedInput, buildRuntime.queryCtx);
70	
71	          return { path, state: buildRuntime.stateSignal() };
72	        })
73	      );
74	    }
75	  }
76	
77	  const builtStates = await Promise.all(buildTasks);
78	
79	  for (const { path, state } of builtStates) {
80	    // Shared paths intentionally merge so multiple queries can contribute one serialized file.
81	    store[path] = path in store ? toMerged(store[path] as object, state as object) : state;
82	  }
83	
84	  return store;
85	}
