type RuntimeServiceDefinition = ServiceDefinition<unknown, Queries<unknown>, Commands<unknown>>;
/** Type-erased service instance handed back to registry consumers. */
type RegisteredServiceInstance = ServiceInstance<unknown, Queries<unknown>, Commands<unknown>>;
