const serviceRegistry = new Map<string, RegistryEntry>();

/**
 * Applies handler overrides to a set of operation definitions.
 *
 * Only known operation names are replaced; the schema, description, and any static/preload metadata
 * of each definition are preserved so the runtime keeps validating exactly as it did before.
 */
function withHandlerOverrides<TDefs extends Record<string, { handler: unknown }>>(
  defs: TDefs,
  overrides?: Partial<Record<keyof TDefs, unknown>>
): TDefs {
  if (!overrides) {
    return defs;
  }

  return Object.fromEntries(
    Object.entries(defs).map(([name, def]) => {
      const override = overrides[name as keyof TDefs];
      return [name, override ? { ...def, handler: override } : def];
    })
  ) as TDefs;
