/** Removes every registered service from the global registry. */
export function clearRegistry(): void {
  serviceRegistry.clear();
}

/**
 * Resolves the registered service instance for a given id.
 *
 * The async contract lets handlers await cross-service lookups uniformly whether they run at runtime
 * or during a static build preload, and surfaces a categorized error when the id is unknown.
 */
export async function getService(id: string): Promise<RegisteredServiceInstance> {
  const entry = serviceRegistry.get(id);

  if (!entry) {
    throw new MissingServiceError({ id });
  }

  return entry.instance;
}

/** Returns every currently registered service instance without resolving asynchronously. */
export function getRegisteredServices(): RegisteredServiceInstance[] {
  return Array.from(serviceRegistry.values(), (entry) => entry.instance);
}

/** Returns a compact summary of every registered service. */
export async function listServices(): Promise<ServiceSummary[]> {
  return Array.from(serviceRegistry.values(), ({ definition }) => ({
    id: definition.id,
    description: definition.description,
    queryNames: Object.keys(definition.queries),
    commandNames: Object.keys(definition.commands),
  }));
}

/** Maps a set of operation definitions to their schema-reference descriptors. */
function describeOperations(
  operations: Record<string, { description?: string; input: AnySchema; output: AnySchema }>
): Record<string, OperationDescriptor> {
  return Object.fromEntries(
    Object.entries(operations).map(([name, def]) => [
      name,
      { description: def.description, input: def.input, output: def.output },
    ])
  );
}

/** Returns the full descriptor, including schema references, for one registered service. */
export async function describeService(id: string): Promise<ServiceDescriptor> {
  const entry = serviceRegistry.get(id);

  if (!entry) {
    throw new MissingServiceError({ id });
  }

  const { definition } = entry;

  return {
    id: definition.id,
    description: definition.description,
    queries: describeOperations(definition.queries),
    commands: describeOperations(definition.commands),
  };
}

